import React, { useState } from 'react';
import playSound from '../utils/soundManager';
import { Gamepad2 } from 'lucide-react';

const ControllerSetupPopup = ({ onComplete }) => {
  const [selectedController, setSelectedController] = useState('xbox');

  const handleControllerSelect = (type) => {
    playSound('select');
    setSelectedController(type);
  };

  const handleContinue = () => {
    playSound('select');
    localStorage.setItem('controllerType', selectedController);
    localStorage.setItem('controllerSetupComplete', 'true');
    onComplete();
  };

  const getButtonColor = (controllerType, button) => {
    const colors = {
      xbox: {
        'A': '#107C10', 'B': '#E81123', 'X': '#0078D4', 'Y': '#FFB900'
      },
      playstation: {
        '✕': '#0070CC', // Blue (X)
        '○': '#CD2A2A', // Proper Red (Circle)
        '□': '#E91E63', // Pink (Square)
        '△': '#27AE60'  // Green (Triangle)
      },
      nintendo: {
        'A': '#2C2C2C', 'B': '#2C2C2C', 'X': '#2C2C2C', 'Y': '#2C2C2C'
      }
    };
    return colors[controllerType]?.[button] || '#8E8E8E';
  };

  const controllers = [
    {
      id: 'xbox',
      name: 'Xbox',
      buttons: ['A', 'B', 'X', 'Y']
    },
    {
      id: 'playstation',
      name: 'PlayStation',
      buttons: ['✕', '○', '□', '△']
    },
    {
      id: 'nintendo',
      name: 'Nintendo',
      buttons: ['A', 'B', 'X', 'Y']
    }
  ];

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0, 0, 0, 0.95)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 10000,
      animation: 'fadeIn 0.3s ease-in'
    }}>
      <div style={{
        background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)',
        borderRadius: '20px',
        padding: '50px',
        maxWidth: '700px',
        width: '90%',
        boxShadow: '0 20px 60px rgba(0, 0, 0, 0.8)',
        border: '2px solid rgba(255, 255, 255, 0.1)',
        animation: 'scaleIn 0.4s ease-out'
      }}>
        <div style={{
          textAlign: 'center',
          marginBottom: '40px'
        }}>
          <Gamepad2 size={64} color="#667eea" style={{ marginBottom: '20px' }} />
          <h1 style={{
            fontSize: '2.2rem',
            fontWeight: '700',
            color: '#fff',
            marginBottom: '15px'
          }}>
            Welcome to Vortex Prime
          </h1>
          <p style={{
            fontSize: '1.1rem',
            color: 'rgba(255, 255, 255, 0.7)',
            lineHeight: '1.6'
          }}>
            Select your primary controller type to customize button prompts throughout the app
          </p>
        </div>

        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: '20px',
          marginBottom: '40px'
        }}>
          {controllers.map((controller) => (
            <div
              key={controller.id}
              onClick={() => handleControllerSelect(controller.id)}
              style={{
                background: selectedController === controller.id
                  ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
                  : 'rgba(255, 255, 255, 0.05)',
                border: selectedController === controller.id
                  ? '3px solid #90EE90'
                  : '2px solid rgba(255, 255, 255, 0.1)',
                borderRadius: '15px',
                padding: '30px 20px',
                cursor: 'pointer',
                transition: 'all 0.3s',
                textAlign: 'center',
                position: 'relative'
              }}
              onMouseEnter={(e) => {
                if (selectedController !== controller.id) {
                  e.currentTarget.style.background = 'rgba(255, 255, 255, 0.1)';
                  e.currentTarget.style.transform = 'translateY(-5px)';
                }
              }}
              onMouseLeave={(e) => {
                if (selectedController !== controller.id) {
                  e.currentTarget.style.background = 'rgba(255, 255, 255, 0.05)';
                  e.currentTarget.style.transform = 'translateY(0)';
                }
              }}
            >
              {selectedController === controller.id && (
                <div style={{
                  position: 'absolute',
                  top: '10px',
                  right: '10px',
                  background: '#90EE90',
                  color: '#000',
                  padding: '4px 10px',
                  borderRadius: '15px',
                  fontSize: '0.7rem',
                  fontWeight: '700'
                }}>
                  ✓
                </div>
              )}

              <div style={{
                display: 'flex',
                gap: '6px',
                justifyContent: 'center',
                marginBottom: '15px'
              }}>
                {controller.buttons.map((button, idx) => {
                  const isPlayStation = controller.id === 'playstation';
                  const isXbox = controller.id === 'xbox';
                  const isNintendo = controller.id === 'nintendo';
                  const buttonColor = getButtonColor(controller.id, button);
                  
                  // Xbox: gradient background with colored text
                  if (isXbox) {
                    return (
                      <div
                        key={idx}
                        style={{
                          background: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 50%, #0a0a0a 100%)',
                          width: '36px',
                          height: '36px',
                          borderRadius: '50%',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          fontSize: '1.1rem',
                          fontWeight: '700',
                          color: buttonColor,
                          border: '2.5px solid #2a2a2a',
                          boxShadow: '0 3px 8px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.05), inset 0 -1px 2px rgba(0,0,0,0.5)',
                          textShadow: `0 1px 3px ${buttonColor}80`
                        }}
                      >
                        {button}
                      </div>
                    );
                  }
                  
                  // PlayStation: black background with colored symbols only
                  if (isPlayStation) {
                    return (
                      <div
                        key={idx}
                        style={{
                          background: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 50%, #0a0a0a 100%)',
                          width: '36px',
                          height: '36px',
                          borderRadius: '50%',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          fontSize: '1.1rem',
                          fontWeight: '700',
                          color: buttonColor,
                          border: '2.5px solid #2a2a2a',
                          boxShadow: '0 3px 8px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.05), inset 0 -1px 2px rgba(0,0,0,0.5)',
                          textShadow: `0 1px 3px ${buttonColor}80`
                        }}
                      >
                        {button}
                      </div>
                    );
                  }
                  
                  // Nintendo: solid black with white text
                  if (isNintendo) {
                    return (
                      <div
                        key={idx}
                        style={{
                          background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 50%, #1a1a1a 100%)',
                          width: '36px',
                          height: '36px',
                          borderRadius: '50%',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          fontSize: '1rem',
                          fontWeight: '700',
                          color: '#ffffff',
                          border: '2.5px solid #3a3a3a',
                          boxShadow: '0 3px 8px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.08), inset 0 -1px 2px rgba(0,0,0,0.5)',
                          textShadow: '0 1px 2px rgba(0,0,0,0.8)'
                        }}
                      >
                        {button}
                      </div>
                    );
                  }
                  
                  return null;
                })}
              </div>

              <h3 style={{
                fontSize: '1.3rem',
                fontWeight: '700',
                color: '#fff',
                marginBottom: '8px'
              }}>
                {controller.name}
              </h3>
            </div>
          ))}
        </div>

        <button
          onClick={handleContinue}
          style={{
            width: '100%',
            padding: '18px',
            fontSize: '1.2rem',
            fontWeight: '700',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            cursor: 'pointer',
            transition: 'all 0.3s',
            boxShadow: '0 6px 20px rgba(102, 126, 234, 0.4)'
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'translateY(-2px)';
            e.target.style.boxShadow = '0 8px 25px rgba(102, 126, 234, 0.6)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'translateY(0)';
            e.target.style.boxShadow = '0 6px 20px rgba(102, 126, 234, 0.4)';
          }}
        >
          Continue
        </button>

        <p style={{
          textAlign: 'center',
          marginTop: '20px',
          fontSize: '0.85rem',
          color: 'rgba(255, 255, 255, 0.5)'
        }}>
          You can change this later in System Settings → Controller
        </p>
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes scaleIn {
          from { transform: scale(0.9); opacity: 0; }
          to { transform: scale(1); opacity: 1; }
        }
      `}</style>
    </div>
  );
};

export default ControllerSetupPopup;
